g=[[0]*20 for _ in range(20)]
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
markers=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in markers: g[r][c]=1
# Extend each row of the rectangle to an edge in each direction unless a marker lies in that direction.
for r in range(2,9):
    for direction in (-1,1):
        blocked=any(rr==r and ((cc<9) if direction==-1 else (cc>15)) for rr,cc in markers)
        if not blocked:
            cols=range(0,9) if direction==-1 else range(16,20)
            for c in cols:
                if g[r][c]==0: g[r][c]=2
# Extend each column upward/downward likewise.
for c in range(9,16):
    for direction in (-1,1):
        blocked=any(cc==c and ((rr<2) if direction==-1 else (rr>8)) for rr,cc in markers)
        if not blocked:
            rows=range(0,2) if direction==-1 else range(9,20)
            for r in rows:
                if g[r][c]==0: g[r][c]=2
